1	package water
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"testing"
8		"time"
9	)
10	
11	// 本文件保护“打开本地数据”时的状态完整性校验：每份已保存样品都必须明确写
12	// 有三种状态之一（pending、confirmed、voided）。status 字段缺失、为 null、
13	// 为空字符串，或写成任何其他字符串（含带首尾空白、大小写不同的写法）都是
14	// 损坏记录，整次 Open 以 ErrCorruptRecord 失败，返回 nil 存放，错误信息点
15	// 到具体样品编号并区分状态缺失与不支持的状态值；原测量完整、逐项判定齐全
16	// 或作废原因仍在都不能代替明确的状态，也不能据此猜出它原来是否作废。同一
17	// 文件中其他样品正常也不只读入正常部分；打开失败不改写原文件、不补状态。
18	
19	// 状态字段整个缺失的样品（其余内容完整，甚至保留了作废原因）必须整次拒绝：
20	// 不能凭“样品污染”的作废原因猜出它原来是 voided。
21	func TestOpenMissingStatusField(t *testing.T) {
22		dir := t.TempDir()
23		raw := `{
24	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
25	  "samples": {
26	    "S1": {"id": "S1", "pointId": "P1", "sampledAt": "` +
27			at(10, 0).Format(time.RFC3339Nano) + `",
28	      "measurements": [{"item": "pH", "value": 7}],
29	      "voidReason": "样品污染"}
30	  }
31	}`
32		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), []byte(raw), 0o644); err != nil {
33			t.Fatalf("write data file: %v", err)
34		}
35		assertOpenRejects(t, dir, "S1", "", true)
36	}
37	
38	// 状态保存为 JSON null：与字段缺失一样是状态缺失，整次打开失败。
39	func TestOpenNullStatus(t *testing.T) {
40		dir := t.TempDir()
41		raw := `{
42	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
43	  "samples": {
44	    "S1": {"id": "S1", "pointId": "P1", "sampledAt": "` +
45			at(10, 0).Format(time.RFC3339Nano) + `",
46	      "measurements": [{"item": "pH", "value": 7}], "status": null}
47	  }
48	}`
49		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), []byte(raw), 0o644); err != nil {
50			t.Fatalf("write data file: %v", err)
51		}
52		assertOpenRejects(t, dir, "S1", "", true)
53	}
54	
55	// 状态为空字符串同样是状态缺失，不能当成待判定接受。
56	func TestOpenEmptyStatus(t *testing.T) {
57		dir := t.TempDir()
58		writeDiskFile(t, dir, diskState{
59			Points: openPoints(),
60			Samples: map[string]*Sample{
61				"S1": {
62					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
63					Measurements: []Measurement{{Item: openPH, Value: 7}},
64					Status:       "",
65				},
66			},
67		})
68		assertOpenRejects(t, dir, "S1", "", true)
69	}
70	
71	// 状态缺失但逐项判定完整且自洽：即使记录保留了完整逐项判定，也不能据此
72	// 猜出它原来是已确认还是已作废，整次打开失败。
73	func TestOpenMissingStatusWithCompleteResults(t *testing.T) {
74		dir := t.TempDir()
75		writeDiskFile(t, dir, diskState{
76			Points: openPoints(),
77			Samples: map[string]*Sample{
78				"S1": {
79					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
80					Measurements: phTurbMeasurements(),
81					Results:      phTurbResults(),
82					Exceeded:     true,
83					Status:       "",
84				},
85			},
86		})
87		assertOpenRejects(t, dir, "S1", "", true)
88	}
89	
90	// 未支持的状态字符串：错误信息中原样带出未知字符串，不能自动整理后接受。
91	func TestOpenUnknownStatus(t *testing.T) {
92		dir := t.TempDir()
93		writeDiskFile(t, dir, diskState{
94			Points: openPoints(),
95			Samples: map[string]*Sample{
96				"S1": {
97					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
98					Measurements: []Measurement{{Item: openPH, Value: 7}},
99					Status:       "archived",
100				},
101			},
102		})
103		assertOpenRejects(t, dir, "S1", "archived", false)
104	}
105	
106	// 带首尾空白、大小写不同的写法都不合法：不能去掉空白或统一大小写后接受。
107	func TestOpenStatusNotNormalized(t *testing.T) {
108		for _, status := range []Status{" pending", "pending ", "Pending", "CONFIRMED", " Voided "} {
109			t.Run(string(status), func(t *testing.T) {
110				dir := t.TempDir()
111				writeDiskFile(t, dir, diskState{
112					Points: openPoints(),
113					Samples: map[string]*Sample{
114						"S1": {
115							ID: "S1", PointID: "P1", SampledAt: at(10, 0),
116							Measurements: []Measurement{{Item: openPH, Value: 7}},
117							Status:       status,
118						},
119					},
120				})
121				assertOpenRejects(t, dir, "S1", string(status), false)
122			})
123		}
124	}
125	
126	// 同一文件中其他样品完全正常，也不能只读入正常部分：一份状态损坏即整次失败。
127	func TestOpenCorruptStatusRejectsWholeFile(t *testing.T) {
128		dir := t.TempDir()
129		writeDiskFile(t, dir, diskState{
130			Points: openPoints(),
131			Samples: map[string]*Sample{
132				"S1": {
133					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
134					Measurements: []Measurement{{Item: openPH, Value: 7}},
135					Status:       StatusPending,
136				},
137				"S2": {
138					ID: "S2", PointID: "P1", SampledAt: at(11, 0),
139					Measurements: []Measurement{{Item: openPH, Value: 6}},
140					Status:       "",
141				},
142			},
143		})
144		assertOpenRejects(t, dir, "S2", "", true)
145	}
146	
147	// 三种合法状态原样读入：待判定可确认，确认后作废的样品保留原测量、原判定
148	// 与原因，不能再次确认，也不成为最近有效结果。
149	func TestOpenLegalStatusesUnchanged(t *testing.T) {
150		dir := t.TempDir()
151		writeDiskFile(t, dir, diskState{
152			Points: openPoints(),
153			Limits: map[string][]Limit{
154				diskLimitKey("P1", openPH): {{PointID: "P1", Item: openPH, Value: 8, Effective: openEff()}},
155			},
156			Samples: map[string]*Sample{
157				"S1": {
158					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
159					Measurements: []Measurement{{Item: openPH, Value: 7}},
160					Status:       StatusPending,
161				},
162				"S2": {
163					ID: "S2", PointID: "P1", SampledAt: at(11, 0),
164					Measurements: []Measurement{{Item: openPH, Value: 9}},
165					Status:       StatusConfirmed,
166					Results: []ItemResult{
167						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
168					},
169					Exceeded: true,
170				},
171				"S3": {
172					ID: "S3", PointID: "P1", SampledAt: at(12, 0),
173					Measurements: []Measurement{{Item: openPH, Value: 6}},
174					Status:       StatusVoided, VoidReason: "样品污染",
175				},
176				"S4": {
177					ID: "S4", PointID: "P1", SampledAt: at(13, 0),
178					Measurements: []Measurement{{Item: openPH, Value: 5}},
179					Status:       StatusVoided, VoidReason: "复测确认样品污染",
180					Results: []ItemResult{
181						{Item: openPH, Value: 5, Limit: 8, LimitEffective: openEff(), Exceeded: false},
182					},
183					Exceeded: false,
184				},
185			},
186		})
187		st, err := Open(dir)
188		if err != nil {
189			t.Fatalf("合法状态应正常打开: %v", err)
190		}
191		defer st.Close()
192		// 确认后作废的样品不能再次确认。
193		if _, err := st.Confirm("S4"); !errors.Is(err, ErrVoided) {
194			t.Fatalf("确认后作废的样品不能再确认，got %v", err)
195		}
196		// 最近有效结果跳过作废与待判定，取 S2。
197		latest, ok, err := st.LatestResult("P1")
198		if err != nil || !ok || latest.ID != "S2" {
199			t.Fatalf("最近有效结果应为 S2，got %v, ok=%v, err=%v", latest.ID, ok, err)
200		}
201		// 待判定样品照常确认。
202		smp, err := st.Confirm("S1")
203		if err != nil || smp.Status != StatusConfirmed {
204			t.Fatalf("待判定样品应可确认，got %v, %v", smp.Status, err)
205		}
206	}
