311	// 完整记录按项目名对应：两个列表排列顺序不同不影响读入；读入后测量与判定
312	// 仍各自保留原有顺序，已保存的上限、生效时间、逐项结论与整份超标标记原样保留。
313	func TestOpenCompleteRecordOrderPreserved(t *testing.T) {
314		dir := t.TempDir()
315		wantMeas := phTurbMeasurements() // pH 在前、浊度在后
316		wantResults := phTurbResults()   // 浊度在前、pH 在后（故意相反）
317		writeDiskFile(t, dir, diskState{
318			Points: openPoints(),
319			Samples: map[string]*Sample{
320				"S1": {
321					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
322					Measurements: wantMeas,
323					Status:       StatusConfirmed, Exceeded: true,
324					Results: wantResults,
325				},
326			},
327		})
328		s, err := Open(dir)
329		if err != nil {
330			t.Fatalf("完整记录（顺序相反）应正常读入: %v", err)
331		}
332		defer s.Close()
333	
334		latest, ok, err := s.LatestResult("P1")
335		if err != nil || !ok || latest.ID != "S1" {
336			t.Fatalf("最近有效结果应指向 S1: %+v ok=%v err=%v", latest, ok, err)
337		}
338		// 原测量顺序保留。
339		if len(latest.Measurements) != 2 ||
340			latest.Measurements[0].Item != openPH || latest.Measurements[0].Value != 9 ||
341			latest.Measurements[1].Item != openTurb || latest.Measurements[1].Value != 4 {
342			t.Fatalf("原测量顺序必须保留: %+v", latest.Measurements)
343		}
344		// 判定顺序保留。
345		if len(latest.Results) != 2 ||
346			latest.Results[0].Item != openTurb || latest.Results[0].Value != 4 ||
347			latest.Results[1].Item != openPH || latest.Results[1].Value != 9 {
348			t.Fatalf("逐项判定顺序必须保留: %+v", latest.Results)
349		}
350		// 已保存的上限、生效时间、逐项结论与整份超标标记原样保留，不重新计算。
351		turb := latest.Results[0]
352		if turb.Limit != 4 || !turb.LimitEffective.Equal(openEff()) || turb.Exceeded {
353			t.Fatalf("浊度判定依据应原样保留: %+v", turb)
354		}
355		ph := latest.Results[1]
356		if ph.Limit != 8 || !ph.LimitEffective.Equal(openEff()) || !ph.Exceeded {
357			t.Fatalf("pH 判定依据应原样保留: %+v", ph)
358		}
359		if !latest.Exceeded {
360			t.Fatalf("整份超标标记应原样保留为 true")
361		}
362		// 重复确认返回同一份已保存依据。
363		again, err := s.Confirm("S1")
364		if err != nil {
365			t.Fatalf("重复确认: %v", err)
366		}
367		if len(again.Results) != 2 || again.Results[0].Item != openTurb ||
368			again.Results[1].Item != openPH || !again.Exceeded {
369			t.Fatalf("重复确认应返回原保存依据: %+v", again.Results)
370		}
371	}
