				ID: "S1", PointID: "P1", SampledAt: at(10, 0),
				Measurements: []Measurement{{Item: openPH, Value: 0}, {Item: openTurb, Value: 0}},
				Status:       StatusConfirmed, Exceeded: false,
				Results: bad,
			},
		},
	})
	assertOpenRejects(t, dir, "S1", openPH, false)
}

