	if err != nil || len(list) != 1 {
		t.Fatalf("按点列表应能查到作废样品: %+v err=%v", list, err)
	}
	smp := list[0]
	if smp.Status != StatusVoided || smp.VoidReason != reason {
		t.Fatalf("作废原因必须原样保留，不为读取改写: %+v", smp)
	}
