		t.Fatalf("作废样品不应作为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
	}
	if _, err := s.Confirm("S1"); !errors.Is(err, ErrVoided) {
		t.Fatalf("已作废样品再确认应被拒绝，got %v", err)
	}
}

